package com.game_manager.gm.workflow; import static org.assertj.core.api.Assertions.*; import com.game_manager.gm.common.error.ApplicationException; import com.game_manager.gm.workflow.dto.WorkflowDefinitionRequest; import java.util.*; import org.junit.jupiter.api.Test;
class WorkflowDefinitionValidatorTest {WorkflowDefinitionValidator validator=new WorkflowDefinitionValidator();@Test void acceptsPilotAndRejectsUnsupportedRoleAndBrokenTarget(){assertThatCode(()->validator.validate(valid())).doesNotThrowAnyException();var invalid=new WorkflowDefinitionRequest("EXPENSE_APPROVAL","Expense","START",List.of(new WorkflowDefinitionRequest.Step("START","Start","SCRIPT",24,12,null)),List.of(new WorkflowDefinitionRequest.Transition("START","APPROVE","MISSING",false)),true);assertThatThrownBy(()->validator.validate(invalid)).isInstanceOf(ApplicationException.class);}@Test void rejectsDuplicateTransition(){var v=valid();var duplicate=new ArrayList<>(v.transitions());duplicate.add(v.transitions().getFirst());assertThatThrownBy(()->validator.validate(new WorkflowDefinitionRequest(v.key(),v.name(),v.initialStep(),v.steps(),duplicate,true))).isInstanceOf(ApplicationException.class);}static WorkflowDefinitionRequest valid(){return new WorkflowDefinitionRequest("EXPENSE_APPROVAL","Expense","MANAGER",List.of(new WorkflowDefinitionRequest.Step("MANAGER","Manager","ADMIN",24,12,"OWNER"),new WorkflowDefinitionRequest.Step("OWNER","Owner","OWNER",24,12,null)),List.of(new WorkflowDefinitionRequest.Transition("MANAGER","APPROVE","OWNER",false),new WorkflowDefinitionRequest.Transition("MANAGER","REJECT","REJECTED",true),new WorkflowDefinitionRequest.Transition("OWNER","APPROVE","APPROVED",false),new WorkflowDefinitionRequest.Transition("OWNER","REJECT","REJECTED",true)),true);}}
